document.addEventListener("DOMContentLoaded",function(){let e=document.getElementById("field-name").querySelector(".form-control"),t=document.getElementById("field-email").querySelector(".form-control"),d=e.value,n=t.value,l=document.getElementById("button-name").querySelector(".btn"),o=document.getElementById("button-email").querySelector(".btn");l.disabled=!0,o.disabled=!0,e.addEventListener("input",()=>{e.value!=d?l.disabled=!1:l.disabled=!0}),t.addEventListener("input",()=>{t.value!=n?o.disabled=!1:o.disabled=!0})});